import functools

def repeat(times):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return [func(*args, **kwargs) for _ in range(times)]
        return wrapper
    return decorator

counter = 0

@repeat(3)
def roll():
    global counter
    counter += 1
    return counter

print(roll())

from contextlib import contextmanager

@contextmanager
def section(name):
    print("start", name)
    try:
        yield
    finally:
        print("end", name)

with section("a"):
    print("body")
try:
    with section("b"):
        raise RuntimeError("boom")
except RuntimeError:
    print("caught")

