import functools

def traced(func):
    @functools.wraps(func)
    def wrapper(*args):
        result = func(*args)
        wrapper.log.append(f"{func.__name__}({', '.join(map(str, args))}) -> {result}")
        return result
    wrapper.log = []
    return wrapper

@traced
def add(a, b):
    return a + b

@traced
def mul(a, b):
    return a * b

add(1, 2)
mul(3, 4)
add(5, 6)
print(add.log)
print(mul.log)
print(sum(len(f.log) for f in (add, mul)))

