import functools

def make_flaky(fail_times, state):
    def call():
        state["calls"] += 1
        if state["calls"] <= fail_times:
            raise ConnectionError(f"failure {state['calls']}")
        return "ok"
    return call

def retry(attempts):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except ConnectionError:
                    if attempt == attempts:
                        raise
        return wrapper
    return decorator

state1 = {"calls": 0}
fetch1 = retry(3)(make_flaky(2, state1))
print(fetch1(), state1["calls"])

state2 = {"calls": 0}
fetch2 = retry(2)(make_flaky(99, state2))
try:
    fetch2()
except ConnectionError as error:
    print(error, state2["calls"])

class Staging:
    def __init__(self, store):
        self.store = store
        self.pending = None

    def __enter__(self):
        self.pending = dict(self.store)
        return self.pending

    def __exit__(self, exc_type, exc, tb):
        if exc_type is None:
            self.store.clear()
            self.store.update(self.pending)
        return False

store = {"a": 1, "b": 1}
with Staging(store) as pending:
    pending.update({"a": 2, "c": 3})
print(store)
try:
    with Staging(store) as pending:
        pending["z"] = 9
        raise ValueError("fail")
except ValueError:
    pass
print(store)

